 2\overset{0}{\mathrm{Hg}}-2\overline{e}= 2\overset{+1}{\mathrm{Hg}}& 
 \end{array}
 \right| \left. \begin{array}{ c c }
 \mathrm{\stackrel{}{2} }& \\
 \mathrm{\stackrel{}{3} }& 
 \end{array}\right| 
 \begin{array}{ l l }
 \text{окисник, відновлення}& \\[7pt]
 \text{відновник, окиснення}&
 \end{array}
