 n(\mathrm{Cu})=2,5\ \text{моль}\\[6pt]
 V(\mathrm{O_2})=\frac 12n(\mathrm{Cu})\\[6pt]
 V(\mathrm{O_2})=n(\mathrm{O_2})V_m(\mathrm{O_2})\\[7pt]
 V(\mathrm{O_2})=1,25\ \text{моль}\cdot 22,4\ \text{л/моль}\\[7pt]
 V(\mathrm{O_2})=28\ \text{л}
 \end{gather*} 
