 \begin{gather*}
 \mathrm{
 CaO+H_2O \rightleftarrows Ca(OH)_2;
 }\\[7pt]
 \mathrm{
 Ca(OH)_2\rightarrow Ca^{2+} +2OH^{-}
 }
 \end{gather*} 
