 \underset{1\ \text{моль}}{\overset{1\ \text{моль}}{\mathrm{Na_2O}}}+\mathrm{H_2O}\rightarrow \underset{2\ \text{моль}}{\overset{2\ \text{моль}}{\mathrm{2NaOH}}}
 \\[6pt]
 n(\mathrm{Na_2O})=\frac{m(\mathrm{Na_2O})}{M(\mathrm{Na_2O})}=\frac{62\ \text{г}}{62\ \text{г/моль}}=1\ \text{моль}
